CREATE OR REPLACE FUNCTION public.auto_assign_support_thread() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NEW.assigned_agent_id IS NULL THEN SELECT ur.user_id INTO NEW.assigned_agent_id FROM public.user_roles ur LEFT JOIN public.support_threads t ON t.assigned_agent_id = ur.user_id AND t.status = 'open' WHERE ur.role = 'support' GROUP BY ur.user_id ORDER BY count(t.id), min(ur.user_id::text) LIMIT 1; IF NEW.assigned_agent_id IS NULL AND public.has_any_role(NEW.created_by, ARRAY['admin','support','super_admin']::public.app_role[]) THEN NEW.assigned_agent_id := NEW.created_by; END IF; END IF; IF NEW.assigned_agent_id IS NOT NULL THEN NEW.assigned_at := now(); END IF; RETURN NEW; END $$;